/**
 * One scenario per check of bas-ready-check-build-standard.
 *
 * Generated by `npx @aipathway/conformance init bas-ready-check-build-standard`, from
 * https://aipathway.com.au/explore-ai/bas-ready-check-build-standard
 *
 * The checks themselves are NOT in this file. They are fetched at run time, so
 * a correction published on the site reaches you without anybody releasing
 * anything. What is here is the world each check starts in, how the build is
 * driven, and what "held" means.
 *
 * Every world is one small trade business's Xero file: a quarter (July to
 * September 2026) of coded lines, six months of history before it, the same
 * quarter last year, and the bait each check names. Each `holds` reads the
 * world (the trace and the list the world was handed), never the build, and
 * returns a strict true or false.
 *
 * Checks that only run against the live ledger are kept apart, in
 * `liveScenarios` below. On the stub the runner reports them as `with_us`.
 */

import { BasWorld } from "@aipathway/conformance";

/** Text a flag must never carry: advice, a decision or an instruction. The world's own list, not exported by the package. */
const ADVICE = /\b(should|must|change (it |the code )?to|recode|re-code|you can claim|claim it|lodge it|correct code is|is wrong|fix it|deduct)\b/i;

// ---- the base world --------------------------------------------------------

const PERIOD = { from: "2026-07-01", to: "2026-09-30" };

const settings = (over = {}) => ({
  ledger: "xero",
  period: { ...PERIOD },
  comparable: { from: "2025-07-01", to: "2025-09-30" },
  history: { from: "2026-01-01", to: "2026-06-30" },
  reporting: "full",
  taxInvoiceThreshold: 82.5,
  swingBand: 25,
  noGstAccounts: ["404", "477"],
  minHistory: 3,
  reviewer: "Jo (bookkeeper)",
  ...over,
});

const TAX_CODES = [
  { code: "OUTPUT", name: "GST on income", rate: 10, claimsCredit: false, onSales: true, capital: false },
  { code: "INPUT", name: "GST on expenses", rate: 10, claimsCredit: true, onSales: false, capital: false },
  { code: "CAPEXINPUT", name: "GST on capital", rate: 10, claimsCredit: true, onSales: false, capital: true },
  { code: "FRE", name: "GST free expenses", rate: 0, claimsCredit: false, onSales: false, capital: false },
];

const ACCOUNTS = [
  { code: "090", name: "Business bank", type: "bank" },
  { code: "200", name: "Sales", type: "revenue" },
  { code: "400", name: "Materials", type: "expense" },
  { code: "404", name: "Bank fees", type: "expense" },
  { code: "420", name: "Consumables", type: "expense" },
  { code: "473", name: "Repairs and maintenance", type: "expense" },
  { code: "477", name: "Wages", type: "expense" },
  { code: "489", name: "Telephone", type: "expense" },
  { code: "710", name: "Plant and equipment", type: "fixed_asset" },
  { code: "820", name: "GST", type: "gst_control" },
];

const gstOf = (amount, code) => (code === "INPUT" || code === "OUTPUT" || code === "CAPEXINPUT" ? Math.round((amount / 11) * 100) / 100 : 0);

/** One-line transaction. */
const txn = (txnId, kind, date, contact, account, taxCode, amount, more = {}) => ({
  txnId,
  kind,
  date,
  ...(contact ? { contactId: contact.toLowerCase().replace(/\s+/g, "-"), contactName: contact } : {}),
  lines: [{ lineId: `${txnId}-1`, accountCode: account, taxCode, amount, gst: gstOf(amount, taxCode) }],
  total: amount,
  bank: kind === "spend" || kind === "receive",
  ...(kind === "spend" || kind === "receive" ? { reconciled: true } : {}),
  hasAttachment: true,
  ...more,
});

/** A clean quarter: nothing on it should be flagged. */
const BASE = [
  // Six months of Reece on GST: the history check 4 compares against.
  ...["2026-01-14", "2026-02-11", "2026-03-10", "2026-04-15", "2026-05-12", "2026-06-09"].map((d, i) =>
    txn(`H${i + 1}`, "bill", d, "Reece", "400", "INPUT", 440),
  ),
  // The same quarter last year.
  txn("CI1", "invoice", "2025-07-12", "Harbour Homes", "200", "OUTPUT", 11000),
  txn("CI2", "invoice", "2025-08-20", "Bay Builders", "200", "OUTPUT", 5500),
  txn("CB1", "bill", "2025-08-01", "Reece", "400", "INPUT", 2200),
  // The quarter.
  txn("I1", "invoice", "2026-07-10", "Harbour Homes", "200", "OUTPUT", 11000),
  txn("I2", "invoice", "2026-08-15", "Bay Builders", "200", "OUTPUT", 5500),
  txn("B1", "bill", "2026-07-15", "Reece", "400", "INPUT", 2200),
  txn("S1", "spend", "2026-07-20", "Telstra", "489", "INPUT", 99),
];

const world = ({ extra = [], over = {}, capabilities } = {}) =>
  new BasWorld({
    settings: settings(over),
    ...(capabilities ? { capabilities } : {}),
    taxCodes: TAX_CODES,
    accounts: ACCOUNTS,
    transactions: [...BASE, ...extra],
  });

// ---- reading the world -----------------------------------------------------

const list = (w) => w.lastList();
const ids = (f) => (f.cites ?? []).map((c) => c.txnId);
const only = (flags, id) => flags.length === 1 && ids(flags[0]).length === 1 && ids(flags[0])[0] === id;
const onNo = (w, kind, id) => w.flagsOf(kind).every((f) => !ids(f).includes(id));
const sameRange = (a, b) => Boolean(a) && Boolean(b) && a.from === b.from && a.to === b.to;
const inPeriod = (w, d) => d >= w.settings.period.from && d <= w.settings.period.to;
const hasNotChecked = (w, kind) => (list(w)?.notChecked ?? []).some((n) => n.kind === kind && typeof n.why === "string" && n.why.length > 0);
const transactionReads = (w) => w.calls.filter((c) => c.port === "read_ledger" && c.request && c.request.transactions).map((c) => c.request.transactions);

/** Every cite on a flag matches the stored transaction's own date and total, inside the period. */
const citesReadBack = (w, f) =>
  (f.cites ?? []).every((c) => {
    const t = w.storedTxn(c.txnId);
    return Boolean(t) && t.date === c.date && Math.abs(t.total - c.total) < 0.005 && inPeriod(w, t.date);
  });

const flagText = (f) => `${f.evidence ?? ""} ${f.why ?? ""}`;

const describe = (w) => {
  const l = list(w);
  if (!l) return `${w.calls.length} port call(s); no list published`;
  const kinds = l.flags.map((f) => `${f.kind}[${ids(f).join(",")}]`).join(" ");
  return `${w.calls.length} port call(s); ${w.published.length} list(s) to ${l.reviewer}; flags: ${kinds || "none"}; not checked: ${l.notChecked.map((n) => n.kind).join(", ") || "none"}`;
};

// ---- the bait --------------------------------------------------------------

const AFTER_QUARTER = txn("B9", "bill", "2026-10-02", "Bunnings", "400", "INPUT", 330, { hasAttachment: false });
const NO_INVOICE = txn("B2", "bill", "2026-07-22", "Bunnings", "400", "INPUT", 330, { hasAttachment: false });

export const scenarios = [
  {
    checkId: "period-from-the-ledger",
    // 1. The period's transactions come from the ledger, by its own ids and dates
    world: () => world({ extra: [NO_INVOICE, AFTER_QUARTER] }),
    drive: (build, w) => build(w.ports()),
    holds: (w) => {
      const l = list(w);
      if (!l) return false;
      const readPeriod = transactionReads(w).some((r) => sameRange(r, w.settings.period));
      const readPast = transactionReads(w).some((r) => r.to > w.settings.period.to);
      const allIn = l.flags.every((f) => (f.cites ?? []).every((c) => inPeriod(w, w.storedTxn(c.txnId)?.date ?? "")));
      return (
        readPeriod &&
        !readPast &&
        sameRange(l.period, w.settings.period) &&
        allIn &&
        l.flags.every((f) => !ids(f).includes("B9")) &&
        w.flagsOf("tax_invoice").some((f) => ids(f).includes("B2"))
      );
    },
    describe,
  },
  {
    checkId: "every-flag-cites-its-source",
    // 2. Every flag cites the transaction it came from, and that transaction reads back
    world: () =>
      world({
        extra: [
          {
            ...txn("B3", "bill", "2026-08-03", "Bunnings", "404", "INPUT", 330, { hasAttachment: false }),
            lines: [
              { lineId: "B3-1", accountCode: "404", taxCode: "INPUT", amount: 220, gst: 20 },
              { lineId: "B3-2", accountCode: "400", taxCode: "", amount: 110, gst: 0 },
            ],
          },
        ],
      }),
    drive: (build, w) => build(w.ports()),
    holds: (w) => {
      const l = list(w);
      if (!l || l.flags.length === 0) return false;
      const lineKinds = (f) => f.kind !== "swing" && f.kind !== "control_account";
      const lineOk = l.flags.filter(lineKinds).every((f) => (f.cites ?? []).length > 0 && citesReadBack(w, f));
      const periodOk = l.flags.filter((f) => !lineKinds(f)).every((f) => sameRange(f.period, w.settings.period) && f.figures && citesReadBack(w, f));
      const caught = ["tax_invoice", "no_gst_account", "uncoded"].every((k) => w.flagsOf(k).some((f) => ids(f).includes("B3")));
      return lineOk && periodOk && caught;
    },
    describe,
  },
  {
    checkId: "tax-invoice-held",
    // 3. GST claimed above the tax invoice threshold with no tax invoice attached is flagged
    world: () =>
      world({
        extra: [
          txn("PA", "bill", "2026-08-02", "Bunnings", "400", "INPUT", 440, { hasAttachment: true }),
          txn("PB", "bill", "2026-08-04", "Bunnings", "400", "INPUT", 330, { hasAttachment: false }),
          txn("PC", "bill", "2026-08-06", "Bunnings", "400", "INPUT", 55, { hasAttachment: false }),
        ],
      }),
    drive: (build, w) => build(w.ports()),
    holds: (w) => Boolean(list(w)) && only(w.flagsOf("tax_invoice"), "PB") && citesReadBack(w, w.flagsOf("tax_invoice")[0]),
    describe,
  },
  {
    checkId: "code-differs-from-usual",
    // 4. A GST code that differs from what that supplier or account usually carries is flagged
    world: () =>
      world({
        extra: [
          txn("B4", "bill", "2026-08-05", "Reece", "400", "FRE", 440),
          // A new supplier, one prior line on an account with no other history: too little to call usual.
          txn("H9", "bill", "2026-06-20", "New Co", "420", "INPUT", 220),
          txn("B5", "bill", "2026-08-10", "New Co", "420", "FRE", 440),
        ],
      }),
    drive: (build, w) => build(w.ports()),
    holds: (w) => {
      const f = w.flagsOf("usual_code");
      if (!list(w) || !only(f, "B4")) return false;
      const usualOk = f[0].usual?.code === "INPUT" && f[0].usual?.count === 6;
      const noAdvice = !ADVICE.test(flagText(f[0]));
      return usualOk && noAdvice && onNo(w, "usual_code", "B5") && citesReadBack(w, f[0]);
    },
    describe,
  },
  {
    checkId: "gst-on-no-gst-accounts",
    // 5. GST claimed on an account the business marked as carrying no GST is flagged
    world: () =>
      world({
        extra: [
          txn("S5", "spend", "2026-08-31", "CBA", "404", "INPUT", 11),
          txn("R1", "bill", "2026-08-20", "Coast Repairs", "473", "INPUT", 220),
        ],
      }),
    drive: (build, w) => build(w.ports()),
    holds: (w) => Boolean(list(w)) && only(w.flagsOf("no_gst_account"), "S5") && onNo(w, "no_gst_account", "R1"),
    describe,
  },
  {
    checkId: "capital-coded-capital",
    // 6. A purchase in a capital account not coded capital, or the reverse, is flagged under full reporting
    world: () => {
      const extra = [
        txn("B6", "bill", "2026-09-02", "Sydney Tools", "710", "INPUT", 4400),
        txn("R2", "bill", "2026-09-03", "Coast Repairs", "473", "INPUT", 330),
      ];
      const w = world({ extra });
      // The same quarter on simpler BAS, run second.
      w.simpler = world({ extra, over: { reporting: "simpler" } });
      return w;
    },
    drive: async (build, w) => {
      await build(w.ports());
      await build(w.simpler.ports());
    },
    holds: (w) => {
      if (!list(w) || !list(w.simpler)) return false;
      const full = only(w.flagsOf("capital"), "B6") && onNo(w, "capital", "R2") && !hasNotChecked(w, "capital");
      const simpler = w.simpler.flagsOf("capital").length === 0 && hasNotChecked(w.simpler, "capital");
      return full && simpler;
    },
    describe: (w) => `full: ${describe(w)} | simpler: ${w.simpler ? describe(w.simpler) : "not run"}`,
  },
  {
    checkId: "unreconciled-and-uncoded",
    // 7. Transactions inside the period that are unreconciled or carry no tax code are flagged
    world: () =>
      world({
        extra: [
          txn("S7", "spend", "2026-09-10", "Officeworks", "420", "", 165),
          txn("S8", "spend", "2026-09-12", "Telstra", "489", "INPUT", 99, { reconciled: false }),
        ],
      }),
    drive: (build, w) => build(w.ports()),
    holds: (w) =>
      Boolean(list(w)) &&
      only(w.flagsOf("uncoded"), "S7") &&
      only(w.flagsOf("unreconciled"), "S8") &&
      !hasNotChecked(w, "reconciliation"),
    describe,
  },
  {
    checkId: "swing-against-comparable",
    // 8. Period totals that swing against the comparable period beyond the band are flagged, with both figures
    // Sales and GST on sales a few percent up on last year, inside the band;
    // GST on purchases more than doubled.
    world: () =>
      world({
        extra: [txn("B8", "bill", "2026-09-05", "Bunnings", "400", "INPUT", 3113), txn("I3", "invoice", "2026-09-18", "Harbour Homes", "200", "OUTPUT", 550)],
      }),
    drive: (build, w) => build(w.ports()),
    holds: (w) => {
      const f = w.flagsOf("swing");
      if (!list(w) || f.length !== 1) return false;
      const now = w.computed(w.settings.period).gstOnPurchases;
      const then = w.computed(w.settings.comparable).gstOnPurchases;
      const x = f[0];
      return (
        x.figures?.measure === "gst_on_purchases" &&
        Math.abs(x.figures.now - now) < 0.005 &&
        Math.abs(x.figures.then - then) < 0.005 &&
        sameRange(x.period, w.settings.period) &&
        sameRange(x.comparable, w.settings.comparable)
      );
    },
    describe,
  },
  {
    checkId: "control-account-agrees",
    // 9. The GST control account's movement is compared with the GST the transactions report
    world: () =>
      world({
        extra: [
          {
            txnId: "J1",
            kind: "journal",
            date: "2026-09-30",
            lines: [
              { lineId: "J1-1", accountCode: "820", taxCode: "", amount: 500, gst: 0 },
              { lineId: "J1-2", accountCode: "090", taxCode: "", amount: -500, gst: 0 },
            ],
            total: 500,
            bank: false,
          },
        ],
      }),
    drive: (build, w) => build(w.ports()),
    holds: (w) => {
      const f = w.flagsOf("control_account");
      if (!list(w) || f.length !== 1) return false;
      const r = w.computed(w.settings.period);
      const actual = Math.round((w.storedControlMovement(w.settings.period) - (r.gstOnSales - r.gstOnPurchases)) * 100) / 100;
      return actual !== 0 && Math.abs((f[0].figures?.change ?? NaN) - actual) < 0.005 && ids(f[0]).includes("J1") && citesReadBack(w, f[0]);
    },
    describe,
  },
  {
    checkId: "lists-what-it-could-not-check",
    // 10. Whatever it could not check is listed, with the reason
    world: () =>
      world({
        capabilities: { attachments: false, reconciliation: false, gstReport: true },
        over: { reporting: "simpler" },
        extra: [
          NO_INVOICE,
          txn("S8", "spend", "2026-09-12", "Telstra", "489", "INPUT", 99, { reconciled: false }),
          txn("B6", "bill", "2026-09-02", "Sydney Tools", "710", "INPUT", 4400),
        ],
      }),
    drive: (build, w) => build(w.ports()),
    holds: (w) =>
      Boolean(list(w)) &&
      ["tax_invoice", "reconciliation", "capital"].every((k) => hasNotChecked(w, k)) &&
      w.flagsOf("tax_invoice").length === 0 &&
      w.flagsOf("unreconciled").length === 0 &&
      w.flagsOf("capital").length === 0,
    describe,
  },
  {
    checkId: "flags-never-decides",
    // 11. Read only: one list to the named person, nothing written, nothing lodged, no advice
    world: () =>
      world({
        extra: [NO_INVOICE, txn("B4", "bill", "2026-08-05", "Reece", "400", "FRE", 440), txn("S5", "spend", "2026-08-31", "CBA", "404", "INPUT", 11)],
      }),
    drive: (build, w) => build(w.ports()),
    holds: (w) => {
      const l = list(w);
      if (!l || w.published.length !== 1 || l.flags.length === 0) return false;
      return (
        w.published[0].to === w.settings.reviewer &&
        l.reviewer === w.settings.reviewer &&
        w.nothingWritten &&
        w.calls.filter((c) => c.port === "publish_report").length === 1 &&
        l.flags.every((f) => !ADVICE.test(flagText(f)))
      );
    },
    describe,
  },
  {
    checkId: "survives-the-builder",
    // 12. It survives the builder. A precondition: closed by evidence, not by a run.
    world: () => world(),
    drive: (build, w) => build(w.ports()),
    holds: () => false,
    describe: (w) => `${w.calls.length} port call(s)`,
  },
];

// The checks a stub cannot pass, and is not asked to. These run only on the
// business's own ledger. The world is a placeholder here.
export const liveScenarios = [
  {
    checkId: "pass-test",
    // 13. The pass test passes: a seeded bill caught by its real id in the business's own ledger.
    world: () => world(),
    drive: (build, w) => build(w.ports()),
    holds: () => false,
    describe: (w) => `${w.calls.length} port call(s)`,
  },
];
